
/**
 * The publisher one file reaches through another file's interface, and a client's deadline, on the
 * training repository's own bytes (madarch-8bdc.2.4): the eighteen files the two shapes stand on,
 * generated by `examples/training-repository/generate.mjs` and pruned, then filled by the stages
 * those records need and read by the extract driver at the same commit.
 *
 * The fixture is the driver's shape first: the driver publishes the orders outbox's
 * `code.publishes` edges and the gRPC call's `deadlineMs` on this tree, so the same bytes are the
 * oracle the stage is compared with. The outbox chain crosses `relay.go` (the `Publisher` interface
 * and `Relay.Flush`), `kafka.go` (`KafkaPublisher.Publish` and its `WriteMessages` send),
 * `outbox.go` (the row and the insert) and `main.go` (the wiring), and a static unit sees one file.
 *
 * One cycle is about fifty seconds: the fill plans nine stages over eighteen files, and every other
 * stage of the registry is switched off in the product's manifest.
 */
import { afterAll, beforeAll, describe, expect, test } from 'bun:test';
import { execFileSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, statSync, symlinkSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createPGliteDatabaseOwner, type DatabaseOwner } from '../src/adapters/database-owner.js';
import { createFillOrchestratorService } from '../src/fill/orchestrator-host.js';
import { createEngineStageRegistry } from '../src/fill/stages/index.js';
import { createGraphStore, type EdgeEntry, type GraphStore, type NodeVersionRow } from '../src/graph/index.js';
import { createStagesFill, type StagesFill } from '../src/product/fill-stages.js';
import { extractContracts } from '../src/extract/contracts/index.js';
import { extractCodeWithFacts } from '../src/extract/code/index.js';
import type { ExtractedEdge, ExtractedNode, Extraction, TreeReader } from '../src/extract/records.js';

const GENERATOR = fileURLToPath(new URL('../examples/training-repository/generate.mjs', import.meta.url));
const REPOSITORY = 'training';
const PRODUCT = 'training-shop';

/**
 * The files the two shapes stand on, and no others: the orders relay, its store, its domain and
 * application, its entry point and its manifest; the checkout client, its config and its index; and
 * the two contract documents. Every other file of the generated repository is pruned before the
 * fill, so one cycle is under a minute.
 */
const KEEP: readonly string[] = [
  'contracts/asyncapi/order-events.yaml',
  'contracts/proto/payments.proto',
  'services/checkout/package.json',
  'services/checkout/src/config.ts',
  'services/checkout/src/index.ts',
  'services/checkout/src/payments-client.ts',
  'services/orders/cmd/orders/main.go',
  'services/orders/go.mod',
  'services/orders/go.sum',
  'services/orders/internal/application/order_service.go',
  'services/orders/internal/application/order_service_test.go',
  'services/orders/internal/domain/order.go',
  'services/orders/internal/domain/order_test.go',
  'services/orders/internal/relay/kafka.go',
  'services/orders/internal/relay/relay.go',
  'services/orders/internal/store/db.go',
  'services/orders/internal/store/order_repository.go',
  'services/orders/internal/store/outbox.go',
];

/** The stages these records need; every other stage of the registry is switched off in the manifest. */
const ENABLED: readonly string[] = ['code-facts', 'contracts', 'contracts-code', 'contracts-links', 'inventory', 'snapshot', 'syntax'];

/**
 * Every stage this madarch knows, by the id its declaration names: the engine's own registry names
 * them all over a source that answers no repository, so a stage added later is switched off here
 * without this list knowing its name.
 */
const STAGES: readonly string[] = createEngineStageRegistry().all().map((stage) => stage.id);

/** The properties a stage's row carries as its own envelope, never as the record the driver published. */
const ENVELOPE: ReadonlySet<string> = new Set(['recordKey', 'factKind', 'layer', 'status', 'provenance', 'repository']);

let root = '';
let owner: DatabaseOwner | undefined;
let store: GraphStore | undefined;
let fill: StagesFill | undefined;
let service: ReturnType<typeof createFillOrchestratorService> | undefined;
let driver: Extraction | undefined;
/** The graph's key for each declaration, by the driver's own name for it (`<path>#<qualified name>`). */
let symbolKeys: ReadonlyMap<string, string> = new Map();
/** The graph's key for each file, by the driver's own name for it (`code.file:<path>`). */
let fileKeys: ReadonlyMap<string, string> = new Map();

/** The paths of the generated repository, in code point order, and their bytes. */
function folderReader(dir: string): TreeReader {
  const walk = (prefix: string): string[] => readdirSync(join(dir, prefix === '' ? '.' : prefix)).flatMap((name) => {
    const rel = prefix === '' ? name : `${prefix}/${name}`;
    if (statSync(join(dir, rel)).isDirectory()) return name === '.git' ? [] : walk(rel);
    return [rel];
  });
  const paths = walk('').sort((left, right) => (left < right ? -1 : left > right ? 1 : 0));
  const bytes = new Map<string, Uint8Array>(paths.map((path) => [path, new Uint8Array(readFileSync(join(dir, path)))]));
  return {
    paths,
    read(path: string): Uint8Array {
      const held = bytes.get(path);
      if (held === undefined) throw new Error(`${dir}/${path}: no such path in the pruned repository`);
      return held;
    },
  };
}

/** Deletes every file of the generated repository that is not kept, and the folders that empty. */
function prune(dir: string): void {
  const kept = new Set(KEEP);
  const walk = (prefix: string): void => {
    const folder = prefix === '' ? '.' : prefix;
    for (const name of readdirSync(join(dir, folder))) {
      if (name === '.git') continue;
      const rel = prefix === '' ? name : `${prefix}/${name}`;
      const full = join(dir, rel);
      if (statSync(full).isDirectory()) { walk(rel); if (readdirSync(full).length === 0) rmSync(full, { recursive: true, force: true }); continue; }
      if (!kept.has(rel)) rmSync(full);
    }
  };
  walk('');
}

/** The node properties a read answered, as a record. */
function propertiesOf(row: { readonly properties: unknown }): Record<string, unknown> {
  return row.properties !== null && typeof row.properties === 'object' && !Array.isArray(row.properties)
    ? row.properties as Record<string, unknown>
    : {};
}

/** Every page of one bounded read. */
async function allPages<T>(fetch: (page: { readonly limit: number; readonly after?: string }) => Promise<{ readonly rows: readonly T[]; readonly next: string | null }>): Promise<readonly T[]> {
  const rows: T[] = [];
  let after: string | undefined;
  for (;;) {
    const page = await fetch(after === undefined ? { limit: 1000 } : { limit: 1000, after });
    rows.push(...page.rows);
    if (page.next === null) return rows;
    after = page.next;
  }
}

beforeAll(async () => {
  root = mkdtempSync(join(tmpdir(), 'madarch-contracts-publishers-'));
  const repository = join(root, 'training');
  execFileSync(process.execPath, [GENERATOR, repository], { stdio: ['ignore', 'pipe', 'pipe'] });
  prune(repository);
  const git = (...args: string[]): void => { execFileSync('git', args, { cwd: repository, stdio: ['ignore', 'pipe', 'pipe'] }); };
  git('add', '-A');
  git('commit', '-qm', 'the eighteen files of the two shapes');
  const product = join(root, 'product');
  mkdirSync(join(product, 'repos'), { recursive: true });
  symlinkSync(repository, join(product, 'repos', REPOSITORY), 'dir');
  writeFileSync(join(product, 'workspace.yaml'), [
    'schemaVersion: 1',
    'id: 7b3e1f42-8a6d-4c19-9f30-2d5b8e6a1c72',
    `name: ${PRODUCT}`,
    'repos:',
    `  - name: ${REPOSITORY}`,
    '    url: file:///training',
    'fill:',
    '  stages:',
    ...STAGES.filter((stage) => !ENABLED.includes(stage)).flatMap((stage) => [`    ${stage}:`, '      enabled: false']),
    '',
  ].join('\n'));
  const productGit = (...args: string[]): void => { execFileSync('git', args, { cwd: product, stdio: ['ignore', 'pipe', 'pipe'] }); };
  productGit('init', '-q', '-b', 'main');
  productGit('config', 'user.name', 'Fixture');
  productGit('config', 'user.email', 'fixture@example.invalid');
  productGit('add', '-A');
  productGit('commit', '-qm', 'the product of the pruned training repository');
  owner = createPGliteDatabaseOwner({ btreeGist: true });
  fill = await createStagesFill({ product, database: owner });
  let at = 1_700_000_000_000;
  service = createFillOrchestratorService({
    home: join(root, 'products'), owner, registry: fill.registry, wiring: () => fill!.wiring,
    clock: () => (at += 1_000), limits: { leaseMs: 86_400_000 }, maxPasses: 100_000,
  });
  store = createGraphStore(owner);
  const run = await service.run({ product: fill.product, runId: 'contracts-publishers-1' });
  if (!run.ok) throw new Error(`the fill was refused: ${run.code}: ${run.reason}`);
  if (run.state !== 'succeeded' || !run.settled) {
    const progress = await service.progress(fill.product.folder);
    const events = progress?.events ?? [];
    const unpublished = (run.units ?? []).filter((unit) => unit.state !== 'published');
    const said = unpublished.map((unit) => {
      const own = events.filter((event) => event.unitId === unit.unitId);
      const last = own.filter((event) => ['unit-retried', 'unit-failed', 'unit-refused', 'unit-blocked'].includes(event.type)).at(-1) ?? own.at(-1);
      return `${unit.unitId} (stage ${unit.stageId}, state ${unit.state}, attempt ${String(unit.attempts)}): ${last?.summary ?? 'the run recorded no event for it'}`;
    });
    throw new Error(`the fill did not settle: ${run.state}, settled ${String(run.settled)}; ${String(unpublished.length)} not published:\n${said.join('\n')}`);
  }
  const reader = folderReader(repository);
  const shared = await extractCodeWithFacts(reader);
  driver = await extractContracts(reader, shared.extraction, shared.facts);
  const symbols = await allPages((page) => store!.byProperty('code.symbol', 'repository', REPOSITORY, page));
  const callables = await allPages((page) => store!.byProperty('code.callable', 'repository', REPOSITORY, page));
  const keys = new Map<string, string>();
  for (const node of [...symbols, ...callables]) {
    const held = propertiesOf(node);
    const file = held['file'];
    const qualifiedName = held['qualifiedName'];
    const key = held['recordKey'];
    if (typeof file !== 'string' || typeof qualifiedName !== 'string' || typeof key !== 'string') continue;
    if (keys.has(`${file}#${qualifiedName}`)) continue;
    keys.set(`${file}#${qualifiedName}`, key);
  }
  symbolKeys = keys;
  const files = await allPages((page) => store!.byProperty('code.file', 'repository', REPOSITORY, page));
  fileKeys = new Map(files.flatMap((node) => {
    const held = propertiesOf(node);
    return typeof held['recordKey'] === 'string' && typeof held['path'] === 'string' ? [[held['recordKey'], `code.file:${held['path']}`] as const] : [];
  }));
}, 1_800_000);

afterAll(async () => {
  await service?.stop();
  await owner?.close();
  if (root !== '') rmSync(root, { recursive: true, force: true });
}, 300_000);

/** The graph's key for a driver symbol reference, so one declaration's two names compare. */
function mapKey(reference: string): string {
  if (!reference.startsWith('code.symbol:')) return reference;
  const rest = reference.slice('code.symbol:'.length);
  const at = rest.lastIndexOf('#');
  if (at < 0) return reference;
  return symbolKeys.get(`${rest.slice(0, at)}#${rest.slice(at + 1)}`) ?? reference;
}

/** A value as a text whose key order is its own. */
function canonical(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map((item) => canonical(item)).join(',')}]`;
  if (value !== null && typeof value === 'object') {
    const held = value as Record<string, unknown>;
    return `{${Object.keys(held).sort().map((key) => `${JSON.stringify(key)}:${canonical(held[key])}`).join(',')}}`;
  }
  return JSON.stringify(value) ?? 'undefined';
}

/** One edge as the comparison names it: its relation, its two ends, its discriminator, its properties and its span. */
function edgeText(edge: { readonly kind: string; readonly from: string; readonly to: string; readonly discriminator: string; readonly properties: Record<string, unknown>; readonly span: unknown }): string {
  return canonical({ kind: edge.kind, from: edge.from, to: edge.to, discriminator: edge.discriminator, properties: edge.properties, span: edge.span });
}

/** The driver's edges of one relation. */
function driverEdges(relation: string): string[] {
  if (driver === undefined) throw new Error('the driver did not read the repository');
  return (driver.edges as readonly ExtractedEdge[]).filter((edge) => edge.type === relation).map((edge) => edgeText({
    kind: edge.type, from: mapKey(edge.from), to: mapKey(edge.to), discriminator: edge.discriminator,
    properties: { ...edge.properties }, span: edge.span ?? null,
  })).sort();
}

/** The stage's edges of one relation: only this reading's rows, the envelope read away. */
async function stageEdges(relation: string): Promise<string[]> {
  if (store === undefined) throw new Error('the graph was not opened');
  const rows = await allPages((page) => store!.edgesByProperty(relation, 'repository', REPOSITORY, page));
  return rows.flatMap((entry: EdgeEntry) => {
    const properties = propertiesOf(entry.edge);
    const source = (properties['provenance'] as Record<string, unknown> | undefined)?.['source'] as Record<string, unknown> | undefined;
    if (typeof source?.['system'] !== 'string' || !source['system'].startsWith('madarch-contracts')) return [];
    const held: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(properties)) if (!ENVELOPE.has(key) && key !== 'span' && key !== 'discriminator') held[key] = value;
    return [edgeText({
      kind: entry.edge.relation ?? '', from: graphKeyOf(entry.src), to: graphKeyOf(entry.dst),
      discriminator: typeof properties['discriminator'] === 'string' ? properties['discriminator'] : '', properties: held,
      span: properties['span'] ?? null,
    })];
  }).sort();
}

/** One node's own key, as the driver's own key of the same record: a file by its path. */
function graphKeyOf(node: { readonly properties: unknown }): string {
  const key = String(propertiesOf(node)['recordKey']);
  return fileKeys.get(key) ?? key;
}

/** The stage's records of one kind, for the trace. */
async function stageNodes(kind: string): Promise<readonly NodeVersionRow[]> {
  if (store === undefined) throw new Error('the graph was not opened');
  return allPages((page) => store!.byProperty(kind, 'repository', REPOSITORY, page));
}

describe('the publisher reached through another file\'s interface, and the client\'s deadline', () => {
  test('the driver reads both shapes, so the pruned tree is the oracle', async () => {
    expect(driverEdges('code.publishes').length).toBe(2);
    expect(driverEdges('code.calls-remote').some((record) => record.includes('deadlineMs'))).toBe(true);
  }, 600_000);

  test('the stage publishes the outbox publication the driver reads', async () => {
    expect(await stageEdges('code.publishes')).toEqual(driverEdges('code.publishes'));
  }, 600_000);

  test('the stage proves the deadline the driver reads', async () => {
    expect(await stageEdges('code.calls-remote')).toEqual(driverEdges('code.calls-remote'));
  }, 600_000);
});
